from __future__ import annotations

import json
import os

from ledgerlock import format as fmt
from ledgerlock import store


class ConflictError(Exception):
    """Raised when a mutation targets a key already committed under a different rid."""

    def __init__(self, key, incoming_rid, committed_rid, batch_index=None):
        self.key = key
        self.incoming_rid = incoming_rid
        self.committed_rid = committed_rid
        self.batch_index = batch_index
        msg = (
            f"conflict on key {key!r}: incoming rid {incoming_rid!r} "
            f"!= committed rid {committed_rid!r}"
        )
        if batch_index is not None:
            msg += f" (batch_index={batch_index})"
        super().__init__(msg)


class Ledger:
    def __init__(self, path):
        self.path = os.fspath(path)

    def append(self, operation):
        return append(self, operation)

    def verify(self):
        return verify(self)

    def snapshot(self):
        return snapshot(self)

    def apply_batch(self, operations):
        return apply_batch(self, operations)

    def repair_tail(self):
        return repair_tail(self)


def _read_bytes(path):
    with open(path, "rb") as f:
        return f.read()


def _load_committed(path):
    try:
        raw_lines = store.read_lines(path)
    except FileNotFoundError:
        return [], {}
    committed = {}
    for raw in raw_lines:
        try:
            line = json.loads(raw.decode("utf-8"))
        except Exception:
            continue
        if not isinstance(line, dict):
            continue
        key = line.get("key")
        if isinstance(key, str):
            committed[fmt.normalize_key(key)] = line
    return raw_lines, committed


def _validate_operation(operation):
    op = operation[0]
    if op == "put":
        if len(operation) != 5:
            raise ValueError("put requires (op, key, value, rid, ts)")
        _, raw_key, value, rid, ts = operation
        value_out = value
    elif op == "delete":
        if len(operation) != 4:
            raise ValueError("delete requires (op, key, rid, ts)")
        _, raw_key, rid, ts = operation
        value_out = None
    else:
        raise ValueError(f"unknown op: {op!r}")

    key = fmt.normalize_key(raw_key)
    if key == "":
        raise ValueError("empty key")

    return op, key, value_out, rid, ts


def append(ledger, operation):
    op, key, value, rid, ts = _validate_operation(operation)

    _, committed = _load_committed(ledger.path)
    if key in committed:
        original = committed[key]
        if original.get("id") == rid:
            return dict(original)
        raise ConflictError(
            key=key,
            incoming_rid=rid,
            committed_rid=original.get("id"),
            batch_index=None,
        )

    fields = {"op": op, "key": key, "ts": ts, "id": rid}
    if op == "put":
        fields["value"] = value

    prev_hash = _tail_hash(ledger.path)
    fields["prev_hash"] = prev_hash
    fields["hash"] = fmt.line_hash(prev_hash, fields)

    line_bytes = fmt.canonical_bytes(fields) + b"\n"
    _append_bytes(ledger.path, line_bytes)

    return fields


def _verify_raw_lines(raw_lines):
    if not raw_lines:
        return {"ok": True, "first_bad_index": None}
    prev = fmt.GENESIS
    for i, raw in enumerate(raw_lines):
        try:
            line = json.loads(raw.decode("utf-8"))
        except Exception:
            return {"ok": False, "first_bad_index": i}
        if not isinstance(line, dict):
            return {"ok": False, "first_bad_index": i}
        stored_prev = line.get("prev_hash")
        stored_hash = line.get("hash")
        if stored_prev != prev:
            return {"ok": False, "first_bad_index": i}
        if fmt.line_hash(stored_prev, line) != stored_hash:
            return {"ok": False, "first_bad_index": i}
        prev = stored_hash
    return {"ok": True, "first_bad_index": None}


def verify(ledger):
    raw_lines = store.read_lines(ledger.path)
    return _verify_raw_lines(raw_lines)


def snapshot(ledger):
    try:
        raw_lines = store.read_lines(ledger.path)
    except FileNotFoundError:
        return {}
    state = {}
    for raw in raw_lines:
        try:
            line = json.loads(raw.decode("utf-8"))
        except Exception:
            continue
        if not isinstance(line, dict):
            continue
        key = line.get("key")
        if not isinstance(key, str):
            continue
        key = fmt.normalize_key(key)
        if line.get("op") == "put":
            state[key] = line.get("value")
        elif line.get("op") == "delete":
            state.pop(key, None)
    return dict(sorted(state.items()))


def apply_batch(ledger, operations):
    ops = [tuple(op) for op in operations]

    raw_lines, committed = _load_committed(ledger.path)
    working = dict(committed)

    new_ops = []
    for i, operation in enumerate(ops):
        op, key, value, rid, ts = _validate_operation(operation)

        if key in working:
            committed_rid = working[key].get("id")
            if committed_rid == rid:
                continue
            raise ConflictError(
                key=key,
                incoming_rid=rid,
                committed_rid=committed_rid,
                batch_index=i,
            )

        fields = {"op": op, "key": key, "ts": ts, "id": rid}
        if op == "put":
            fields["value"] = value
        working[key] = fields
        new_ops.append(fields)

    prev_hash = _tail_hash(ledger.path)
    new_line_bytes = []
    for fields in new_ops:
        fields["prev_hash"] = prev_hash
        fields["hash"] = fmt.line_hash(prev_hash, fields)
        prev_hash = fields["hash"]
        new_line_bytes.append(fmt.canonical_bytes(fields) + b"\n")

    out_lines = [raw + b"\n" for raw in raw_lines]
    out_lines.extend(new_line_bytes)

    store.write_atomic(ledger.path, out_lines)
    return len(new_ops)


def repair_tail(ledger):
    path = ledger.path
    data = _read_bytes(path)

    if data == b"":
        return {"ok": True, "repaired": False, "first_bad_index": None}

    ends_with_newline = data.endswith(b"\n")
    split = data.split(b"\n")
    raw_lines = split[:-1] if ends_with_newline else split

    verdict = _verify_raw_lines(raw_lines)
    if verdict["ok"]:
        return {"ok": True, "repaired": False, "first_bad_index": None}

    bad = verdict["first_bad_index"]
    n = len(raw_lines)

    is_tail_truncation = (not ends_with_newline) and (bad == n - 1)
    if not is_tail_truncation:
        return {"ok": False, "repaired": False, "first_bad_index": bad}

    remaining = raw_lines[:-1]
    remaining_verdict = _verify_raw_lines(remaining)
    if remaining_verdict["ok"]:
        store.write_atomic(path, [line + b"\n" for line in remaining])
        return {"ok": True, "repaired": True, "first_bad_index": None}

    return {
        "ok": False,
        "repaired": False,
        "first_bad_index": remaining_verdict["first_bad_index"],
    }


def _tail_hash(path):
    try:
        lines = store.read_lines(path)
    except FileNotFoundError:
        return fmt.GENESIS
    if not lines:
        return fmt.GENESIS
    last = json.loads(lines[-1].decode("utf-8"))
    return last["hash"]


def _append_bytes(path, data):
    with open(path, "ab") as f:
        f.write(data)
        f.flush()
        os.fsync(f.fileno())

